import{_ as a,o as e,c as r,a5 as l}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"碳酸盐","description":"","frontmatter":{"title":"碳酸盐","mineralGroup":"carbonates"},"headers":[],"relativePath":"zh/classification/mineral-groups/carbonates.md","filePath":"zh/classification/mineral-groups/carbonates.md","lastUpdated":1790876393000}'),i={name:"zh/classification/mineral-groups/carbonates.md"};function d(n,t,o,s,c,h){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="碳酸盐" tabindex="-1">碳酸盐 <a class="header-anchor" href="#碳酸盐" aria-label="Permalink to &quot;碳酸盐&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>碳酸盐类涵盖宝石界多个富有特色的品种：</p><ul><li><strong>方解石族</strong>：方解石（含冰洲石）、菱锰矿、菱镁矿、菱铁矿、 蓝纹石（含 Sr 的蓝色方解石变种）</li><li><strong>文石族</strong>：文石（霰石）、珍珠母（生物成因）、珊瑚</li><li><strong>白云石、孔雀石、蓝铜矿</strong>：含水或铜的复杂碳酸盐 碳酸盐普遍硬度较低（Mohs 3–4），多为玉石或有机宝石原料。</li></ul><h2 id="化学式类型" tabindex="-1">化学式类型 <a class="header-anchor" href="#化学式类型" aria-label="Permalink to &quot;化学式类型&quot;">​</a></h2><p>CO₃²⁻ + 二价金属阳离子</p><h2 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h2><p>[CO₃]²⁻ 平面三角形基团与二价金属阳离子（Ca、Mg、Mn、Fe、Cu、 Zn、Ba、Sr）配位。方解石型为三方晶系；文石型为斜方晶系。</p><h2 id="代表性宝石" tabindex="-1">代表性宝石 <a class="header-anchor" href="#代表性宝石" aria-label="Permalink to &quot;代表性宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>化学式</th><th>亚族</th></tr></thead><tbody><tr><td>Calcite / 方解石</td><td>CaCO₃</td><td>calcite</td></tr><tr><td>Rhodochrosite / 菱锰矿</td><td>MnCO₃</td><td>calcite</td></tr><tr><td>Magnesite / 菱镁矿</td><td>MgCO₃</td><td>calcite</td></tr><tr><td>Aragonite / 文石</td><td>CaCO₃</td><td>aragonite</td></tr><tr><td>Malachite / 孔雀石</td><td>Cu₂CO₃(OH)₂</td><td>malachite</td></tr><tr><td>Azurite / 蓝铜矿</td><td>Cu₃(CO₃)₂(OH)₂</td><td>azurite</td></tr><tr><td>Smithsonite / 菱锌矿</td><td>ZnCO₃</td><td>calcite</td></tr></tbody></table><p><em>详见<a href="./intro.html">矿物组总览</a>。</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA：宝石的矿物种、品种与矿物组</a><span>矿物种、宝石品种与矿物组的层级关系</span><small>打开来源 ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat 矿物数据库</a><span>矿物名称、化学组成与分类检索</span><small>打开来源 ↗</small></li></ul></aside>',12)])])}const u=a(i,[["render",d]]);export{p as __pageData,u as default};
